# 6.2 Changes of state · 7Cm.06, 7TWSa.05
# =====================================================================================================
READ["6.2"] = L(
    H("Ice cream on a hot day",
      "Ice cream drips down the cone in the sun, a puddle disappears after the rain, and a bathroom mirror steams up after a shower.",
      "All three are **changes of state**. Can you name each one before you read on?"),
    I("Changes of state",
      "Heating or cooling can change a substance from one state to another.",
      fig={"kind": "sciStates"},
      table=[["Change", "From → to", "Example"], ["**melting**", "solid → liquid", "butter in a hot pan"], ["**freezing**", "liquid → solid", "water in an ice tray"],
             ["**evaporating / boiling**", "liquid → gas", "a puddle drying; a kettle boiling"], ["**condensing**", "gas → liquid", "droplets on a bathroom mirror"]],
      then=["In a change of state only the **arrangement, closeness and movement** of the particles change. The particles themselves stay the same, so **no new substance** is made."]),
    I("Melting and freezing",
      "When a solid is heated, its particles gain energy and vibrate faster. At the **melting point** they have enough energy to break free from their fixed positions and move around each other: the solid has melted.",
      then=["Freezing is the reverse: the liquid's particles lose energy, slow down and lock into a regular pattern. A pure substance **freezes at the same temperature** as it melts: pure water melts and freezes at 0 °C; pure tin melts at 232 °C."]),
    I("Evaporation and boiling",
      "Both turn a liquid into a gas, but they are not the same.",
      table=[["Evaporation", "Boiling"], ["happens at **any** temperature", "happens only at the **boiling point** (water: 100 °C)"],
             ["only at the **surface** of the liquid", "**all through** the liquid – bubbles of gas form inside"], ["slow", "fast"]],
      then=["**Condensation** is the reverse: gas particles cool, lose energy, slow down and come together as a liquid."]),
    I("Predict, watch, explain: the cold bottle",
      "A bottle of water is taken from the fridge and stands in a warm room. After a few minutes the outside is covered in drops. The bottle is sealed, so nothing leaked out.",
      then=["The air contains invisible **water vapour**. When it touches the cold bottle it cools, its particles slow down and come together, and it **condenses** into liquid water."]),
    Y("Name the change",
      grid("s7u06r21", "Which change of state is happening?", ["Melting", "Freezing", "Evaporating", "Condensing"],
           [("wet washing dries on a line", "Evaporating"), ("a glass window mists up on a cold morning", "Condensing"), ("candle wax drips near the flame", "Melting"),
            ("a pond turns to ice in winter", "Freezing")],
           "Ask: what state does it start in, and what state does it end in?", "Water → vapour = evaporating; vapour → droplets = condensing; solid wax → liquid = melting; water → ice = freezing.")),
    I("Investigation: heating ice",
      "Crushed ice in a beaker is heated steadily and the temperature is read every two minutes until the water has boiled for a while. Wear safety goggles.",
      fig={"kind": "linegraph", "x": {"min": 0, "max": 24, "step": 4, "label": "time (minutes)"}, "y": {"min": -10, "max": 110, "step": 20, "label": "temperature (°C)"},
           "series": [{"pts": [[0, -10], [2, 0], [4, 0], [6, 0], [8, 20], [10, 42], [12, 63], [14, 84], [16, 100], [18, 100], [20, 100], [22, 100], [24, 100]]}]},
      then=["The line rises, goes **flat at 0 °C** (the ice is melting), rises again, then goes **flat at 100 °C** (the water is boiling).",
            "During a change of state the energy is used to overcome the forces between particles, so the temperature does not rise. With more ice it would take longer, but the flat parts would stay at 0 °C and 100 °C."]),
    Y("Read the heating curve",
      num("s7u06r22", "Use the graph. For how many minutes was the ice melting (temperature flat at 0 °C)?", 4,
          "Find where the line is flat at 0 °C: from which time to which time?", "Flat from 2 to 6 minutes: 6 − 2 = 4 minutes.",
          errs=[(6, "The flat part starts at 2 minutes, not 0."), (0, "Look at the flat part of the line at 0 °C.")])),
    X("Steam is invisible",
      "Many people call the white cloud above a kettle 'steam'.",
      "Water vapour (steam) is an **invisible gas**. The white cloud is tiny drops of **liquid** water that have already condensed in the cooler air – look closely and there is a clear gap just above the spout."),
    K("Key points",
      "Melting, freezing, evaporating, boiling and condensing are **changes of state**; no new substance forms.",
      "Heating gives particles more energy; cooling takes energy away.",
      "Evaporation: any temperature, at the surface. Boiling: at the boiling point, all through the liquid.",
      "On a heating curve the temperature stays **flat** during a change of state (water: 0 °C and 100 °C)."),
    book=BK(
        [("melting point", "the temperature at which a solid melts (the same as its freezing point)"), ("boiling point", "the temperature at which a liquid boils"),
         ("evaporation", "a liquid turning into a gas at its surface, at any temperature"), ("condensation", "a gas cooling and turning into a liquid"),
         ("heating curve", "a graph of temperature against time as a substance is heated")],
        [], [],
        [Ex("Name the change of state:", ("solid to liquid", "melting"), ("gas to liquid", "condensing"), ("liquid to solid", "freezing"), ("liquid to gas", "evaporating or boiling")),
         Ex("Use the particle model to describe what happens when ice melts.", ans="The particles gain energy and vibrate faster until they break out of their fixed positions and can move around each other."),
         Ex("Give two differences between evaporation and boiling.", ans="Evaporation happens at any temperature and only at the surface; boiling happens at the boiling point and all through the liquid."),
         Ex("Pure gold melts at 1064 °C. At what temperature does liquid gold freeze?", ans="1064 °C"),
         Ex("A student heats twice as much ice as in this lesson. Sketch how her heating curve would differ.",
            ans="Same shape with flat parts at 0 °C and 100 °C, but each part takes longer.", think=True)],
        ["name and describe the changes of state", "explain them using the particle model", "compare evaporation and boiling", "interpret a heating curve"],
        look=["the changes of state diagram", "the flat parts of the heating curve"],
        note="Read it after the video: changes of state, melting and boiling points and the heating curve (answers at the back)."),
)

